CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'ja');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_owner ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER create_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.workspaces (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, settings jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workspaces TO authenticated;
GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_owner ON public.workspaces FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, storage_path text NOT NULL, file_hash text NOT NULL, year integer NOT NULL, status text NOT NULL DEFAULT 'needs_information', original jsonb NOT NULL DEFAULT '{}', details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.documents TO authenticated;
GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_owner ON public.documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX document_owner_year ON public.documents(user_id,year);
CREATE TABLE public.audit_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, document_id uuid, before_value jsonb, after_value jsonb, recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_history TO authenticated;
GRANT ALL ON public.audit_history TO service_role;
ALTER TABLE public.audit_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_owner ON public.audit_history FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.audit_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_history(user_id,document_id,before_value,after_value) VALUES(NEW.user_id,NEW.id,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER document_history AFTER INSERT OR UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.audit_document();
CREATE POLICY private_pdf_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='financial-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY private_pdf_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='financial-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name))='pdf');
CREATE POLICY private_pdf_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='financial-documents' AND (storage.foldername(name))[1]=auth.uid()::text);